// Claude's review tests for A9 (socket rows, Test bar staleness) and A10 (Answered by).
// agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, newProject, type Mock, type Project, type SocketMock, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

function mock(id: string, urlPattern: string, extra: Partial<Mock> = {}): Mock {
  return {
    id,
    enabled: true,
    method: 'GET',
    urlPattern,
    response: { status: 200, headers: { 'content-type': 'application/json' }, body: '{"ok":1}', bodyEncoding: 'text', delayMs: 0 },
    source: 'manual',
    createdAt: 0,
    ...extra,
  };
}

const fakeSocket: SocketMock = {
  id: 'sock1',
  name: 'Fake feed',
  enabled: true,
  kind: 'plain',
  urlPattern: '/ws/fake',
  onConnect: [{ id: 'p1', afterMs: 0, target: '', data: 'hi' }],
  replies: [],
  createdAt: 0,
};

function project(): Project {
  const p = newProject('p1', fixture.origin);
  p.scenarios[0]!.mocks.push(mock('m-named', '/api/named', { name: 'Named one' }), mock('m-bare', '/api/bare'));
  p.scenarios[0]!.sockets = [fakeSocket];
  p.scenarios.push({ id: 'sc2', name: 'Second', mocks: [mock('m-second', '/api/second', { name: 'Second only' })] });
  return p;
}

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function openBoth(p: Project = project()): Promise<{ page: Page; panel: Page }> {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [p] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

function realSocket(page: Page) {
  return page.evaluate(async () => {
    const ws = new WebSocket(`${location.origin.replace('http', 'ws')}/ws/real`);
    const got: string[] = [];
    ws.onmessage = (e) => got.push(String(e.data));
    await new Promise((r) => (ws.onopen = r));
    for (let i = 0; i < 50 && got.length < 1; i++) await new Promise((r) => setTimeout(r, 20));
    ws.send('a');
    for (let i = 0; i < 50 && got.length < 2; i++) await new Promise((r) => setTimeout(r, 20));
    ws.close();
  });
}

test.describe('A9: socket rows', () => {
  test('a real socket open row offers only Mock this socket, with no empty response boxes', async () => {
    const { page, panel } = await openBoth();
    try {
      await realSocket(page);
      await panel.getByTestId('log-row').filter({ hasText: '101' }).first().click();
      await expect(panel.getByTestId('mock-socket')).toBeVisible();
      await expect(panel.getByTestId('mock-this')).toHaveCount(0);
      await expect(panel.getByTestId('response-body')).toHaveCount(0);
      await expect(panel.locator('.log-detail')).not.toContainText('Response Headers');
      await expect(panel.locator('.log-detail')).not.toContainText('Response Body');
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('a socket message row shows its text, and no Mock this', async () => {
    const { page, panel } = await openBoth();
    try {
      await realSocket(page);
      const rows = panel.getByTestId('log-row');
      await rows.filter({ hasText: 'WS ↓' }).first().click();
      await expect(panel.getByTestId('socket-message')).toHaveText('tick 1');
      await expect(panel.getByTestId('mock-this')).toHaveCount(0);
      await expect(panel.getByTestId('mock-socket')).toHaveCount(0);
      await expect(panel.locator('.log-detail')).not.toContainText('Response Headers');

      await rows.filter({ hasText: 'WS ↑' }).first().click();
      await expect(panel.getByTestId('socket-message')).toHaveText('a');
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('an HTTP row keeps Mock this and its response boxes', async () => {
    const { page, panel } = await openBoth();
    try {
      await page.evaluate(async () => (await fetch('/api/goals')).text());
      await panel.getByTestId('log-row').filter({ hasText: '/api/goals' }).first().click();
      await expect(panel.getByTestId('mock-this')).toBeEnabled();
      await expect(panel.getByTestId('response-body')).toBeVisible();
      await expect(panel.getByTestId('socket-message')).toHaveCount(0);
    } finally {
      await panel.close();
      await page.close();
    }
  });
});

test.describe('A9: the Test bar never shows an old result', () => {
  async function runTest(panel: Page) {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('test-method').selectOption('GET');
    await panel.getByTestId('test-url').fill('/api/named');
    await panel.getByTestId('test-run').click();
    await expect(panel.getByTestId('test-status')).toBeVisible();
  }

  test('switching the active scenario clears the result', async () => {
    const { page, panel } = await openBoth();
    try {
      await runTest(panel);
      await panel.getByTestId('scenario-chip').filter({ hasText: 'Second' }).first().click();
      await expect.poll(async () => (await readState()).projects[0]!.activeScenarioId).toBe('sc2');
      await expect(panel.getByTestId('test-status')).toHaveCount(0);
      await expect(panel.getByTestId('test-match')).toHaveCount(0);
      await expect(panel.getByTestId('test-nomatch')).toHaveCount(0);
      // The URL stays, so Test can be pressed again.
      await expect(panel.getByTestId('test-url')).toHaveValue('/api/named');
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('turning a mock off clears the result', async () => {
    const { page, panel } = await openBoth();
    try {
      await runTest(panel);
      await panel.getByTestId('mock-row').filter({ hasText: 'Named one' }).getByTestId('mock-enabled').uncheck();
      await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks[0]!.enabled).toBe(false);
      await expect(panel.getByTestId('test-status')).toHaveCount(0);
      await expect(panel.getByTestId('test-match')).toHaveCount(0);
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('a result survives when nothing changed', async () => {
    const { page, panel } = await openBoth();
    try {
      await runTest(panel);
      await panel.waitForTimeout(500);
      await expect(panel.getByTestId('test-status')).toBeVisible();
    } finally {
      await panel.close();
      await page.close();
    }
  });
});

test.describe('A10: Answered by', () => {
  test('a MOCK row names its mock and scenario, and the link opens it', async () => {
    const { page, panel } = await openBoth();
    try {
      await page.evaluate(async () => (await fetch('/api/named')).text());
      await panel.getByTestId('log-row').filter({ hasText: '/api/named' }).first().click();
      await expect(panel.getByTestId('answered-by')).toHaveText('Answered by: Named one · Default');
      await panel.getByTestId('answered-by-link').click();
      await expect(panel.getByTestId('field-name')).toHaveValue('Named one');
      await expect(panel.getByTestId('field-pattern')).toHaveValue('/api/named');
      await expect(panel.getByTestId('mock-row').filter({ hasText: 'Named one' })).toHaveClass(/selected/);
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('an unnamed mock is named by its pattern', async () => {
    const { page, panel } = await openBoth();
    try {
      await page.evaluate(async () => (await fetch('/api/bare')).text());
      await panel.getByTestId('log-row').filter({ hasText: '/api/bare' }).first().click();
      await expect(panel.getByTestId('answered-by')).toContainText('/api/bare');
      await panel.getByTestId('answered-by-link').click();
      await expect(panel.getByTestId('field-pattern')).toHaveValue('/api/bare');
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('a mock from another scenario names that scenario and opens there', async () => {
    const p = project();
    p.activeScenarioId = 'sc2';
    const { page, panel } = await openBoth(p);
    try {
      await page.evaluate(async () => (await fetch('/api/second')).text());
      await panel.getByTestId('log-row').filter({ hasText: '/api/second' }).first().click();
      await expect(panel.getByTestId('answered-by')).toHaveText('Answered by: Second only · Second');
      await panel.getByTestId('answered-by-link').click();
      await expect(panel.getByTestId('field-name')).toHaveValue('Second only');
      // Its scenario is the one selected, so New mock goes there.
      const second = panel.locator('.scenario-group').filter({ has: panel.locator('.scenario-name-badge', { hasText: /^Second$/ }) });
      await expect(second).toHaveClass(/selected/);
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('a mocked socket row opens its socket mock', async () => {
    const { page, panel } = await openBoth();
    try {
      await page.evaluate(async () => {
        const ws = new WebSocket(`${location.origin.replace('http', 'ws')}/ws/fake`);
        await new Promise((r) => (ws.onmessage = r));
        ws.close();
      });
      await panel.getByTestId('log-row').filter({ hasText: 'MOCK' }).filter({ hasText: '101' }).first().click();
      await expect(panel.getByTestId('answered-by')).toContainText('Fake feed');
      await panel.getByTestId('answered-by-link').click();
      await expect(panel.getByTestId('socket-name')).toHaveValue('Fake feed');
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('a deleted mock is said to be deleted, with no link', async () => {
    const { page, panel } = await openBoth();
    try {
      await page.evaluate(async () => (await fetch('/api/named')).text());
      const s = await readState();
      s.projects[0]!.scenarios[0]!.mocks = s.projects[0]!.scenarios[0]!.mocks.filter((m) => m.id !== 'm-named');
      await session.setState(s);
      await panel.getByTestId('log-row').filter({ hasText: '/api/named' }).first().click();
      await expect(panel.getByTestId('answered-by')).toHaveText('Answered by a mock that was deleted');
      await expect(panel.getByTestId('answered-by-link')).toHaveCount(0);
    } finally {
      await panel.close();
      await page.close();
    }
  });

  test('a real row has no Answered by', async () => {
    const { page, panel } = await openBoth();
    try {
      await page.evaluate(async () => (await fetch('/api/goals')).text());
      await panel.getByTestId('log-row').filter({ hasText: '/api/goals' }).first().click();
      await expect(panel.getByTestId('answered-by')).toHaveCount(0);
    } finally {
      await panel.close();
      await page.close();
    }
  });
});
